using Crestron.AutoUpdateApiCommon;  // From the contract.g.cs
using Crestron.SimplSharp;
using Crestron.SimplSharpPro;
using Crestron.SimplSharpPro.UI;
//Bring in the contract generated by Construct UI plugin
using MainUI;
using Masters2026Nax.Configuration;
using Masters2026Nax.Hardware;
using MessageBroker;

namespace Masters2026Nax
{
    public class UI
    {
        private XpanelForHtml5? myXpanel;
        private Contract? myContract;

        /// <summary>
        /// Creates and initializes a new HTML5 XPanel wrapper.
        ///
        /// This constructor creates the underlying Crestron XPanel object, registers it
        /// with the control system, creates the Gui contract used,
        /// and prepares the panel for communication. 
        /// This constructor performs the one-time setup required for the panel. User
        /// interface logic, event registration, and application behavior should be
        /// implemented elsewhere.
        /// </summary>
        /// <param name="IpId">
        /// The IP ID assigned to the HTML5 XPanel.
        /// </param>
        /// <param name="cs">
        /// The ControlSystem that owns and registers the XPanel.
        /// </param>
        public UI(uint IpId, ControlSystem cs)
        {
            myXpanel = new XpanelForHtml5(IpId, cs);
            myXpanel.OnlineStatusChange += PanelOnlineOfflineEventHandler;
            myContract = new Contract();
            myContract.AddDevice(myXpanel);
            myXpanel.Register();

            CrestronConsole.PrintLine($"Toucpanel REgistered at {IpId.ToString()}");

            // ########################################  Register contract event handlers


            // Main Page source selects
            myContract.MainPage.Source1Select.Button_PressEvent += Source1Select_Button_PressEvent;
            myContract.MainPage.Source2Select.Button_PressEvent += Source2Select_Button_PressEvent;
            myContract.MainPage.Source3Select.Button_PressEvent += Source3Select_Button_PressEvent;
            myContract.MainPage.Source4Select.Button_PressEvent += Source4Select_Button_PressEvent;
            // Source Brocker Connections
            Broker.AddDelegate("Zone1SourceFb", Zone1SetSourceFb);
            Broker.AddDelegate("MediaPlayerCrpcFb", MediaPlayerObjectPlayerFb);

            // Media Player CRPC
            myContract.MediaPlayerPage.MediaPlayer.MediaPlayer_CRPCEvent += MediaPlayer_MediaPlayer_CRPCEvent;

            // Volume buttons
            myContract.MainPage.VolumeUpBtn_PressEvent += MainPage_VolumeUpBtn_PressEvent;
            myContract.MainPage.VolumeDnBtn_PressEvent += MainPage_VolumeDnBtn_PressEvent;
            myContract.MainPage.VolumeMuteBtn_PressEvent += MainPage_VolumeMuteBtn_PressEvent;

            //Label the buttons
            for(ushort i = 0; i < 6; i++)
            {
                myContract.MainPage.Source1Select.Button_Text(i, NaxSourceConfiguration.GetSourceName(1,i));
            }
            
        }



        //VolBtns
        private void MainPage_VolumeMuteBtn_PressEvent(object? sender, UIEventArgs e)
        {
            Broker.SendMessage("VolumeMute", new Message { Digital = e.SigArgs.Sig.BoolValue });
        }
        private void MainPage_VolumeDnBtn_PressEvent(object? sender, UIEventArgs e)
        {
            Broker.SendMessage("VolumeDown", new Message { Digital = e.SigArgs.Sig.BoolValue });
        }
        private void MainPage_VolumeUpBtn_PressEvent(object? sender, UIEventArgs e)
        {
            Broker.SendMessage("VolumeUp", new Message { Digital = e.SigArgs.Sig.BoolValue });
        }
        //ZoneBtns
        private void Source1Select_Button_PressEvent(object? sender, IndexedButtonEventArgs e)
        {

            CrestronConsole.PrintLine($" button = {e.ButtonIndex}   event  = {e}");
            Broker.SendMessage("Zone1Source", new Message { Analog = (ushort)e.ButtonIndex });
        }
        private void Source2Select_Button_PressEvent(object? sender, IndexedButtonEventArgs e)
        {
            Broker.SendMessage("Zone2Source", new Message { Analog = e.SigArgs.Sig.UShortValue });
        }
        private void Source3Select_Button_PressEvent(object? sender, IndexedButtonEventArgs e)
        {
            Broker.SendMessage("Zone3Source", new Message { Analog = e.SigArgs.Sig.UShortValue });
        }
        private void Source4Select_Button_PressEvent(object? sender, IndexedButtonEventArgs e)
        {
            Broker.SendMessage("Zone4Source", new Message { Analog = e.SigArgs.Sig.UShortValue });
        }
        // Panel OnlineOffline
        private void PanelOnlineOfflineEventHandler(GenericBase currentDevice, OnlineOfflineEventArgs args)
        {
            Broker.SendMessage("XpanelOnlineOffline", new Message { Digital = args.DeviceOnLine });
        }

        //###################################   Broker Methods

        // -----------------------------------------------------------------------------
        // Message Broker Feedback Handlers
        //
        // These methods receive feedback messages from the Message Broker and update
        // the touchpanel accordingly.
        //
        // Notice that there is no application logic here. This class doesn't decide
        // what the current source, volume, or mute state should be. That decision has
        // already been made somewhere else in the application. By the time a message
        // reaches one of these methods, our only job is to update the user interface so
        // it reflects the current state of the system.
        //
        // Think of the touchpanel as the dashboard in your car. It doesn't decide how
        // fast you're driving. It simply displays the speed that someone else has
        // already determined.
        //
        // Keeping the UI "dumb" like this makes it much easier to maintain because all
        // state changes flow through the Message Broker. If the system state changes,
        // the broker sends a message, and the touchpanel updates. Nothing more.
        // -----------------------------------------------------------------------------


        private void Zone1SetSourceFb( Message m)
        {
            // Yes, we're brute force clearing every button first. There are only a handful of source
            // buttons, so the code is simple, easy to understand, and guaranteed to leave
            // only one selected. Sometimes the simple solution really is the better one.
            // Could we write 40 lines of code to do it more elegantly and be infinately 
            // expandable?  Sure.   Do we need to?  no.  

            // Also below bothers me for one reason.  This should be able to be a single
            // Method.  But it cant be because Contracts forces tightly coupled code.
            // If I was able to make the button lists an array then we could have used
            // an index and had one method.  This is an instance where join numbers would work better.

            CrestronConsole.PrintLine($"    #### setting TP feedback to {m.Analog}");

            for (ushort i = 0; i < 6; i++)
                myContract!.MainPage.Source1Select.Button_Selected(i, false);  // ! added to stop compiler notices about dereference possibility.

            myContract!.MainPage.Source1Select.Button_Selected(m.Analog, true);

            checkMediaPlayer(m.Analog);
        }
        private void Zone2SetSourceFb(Message m)
        {

            for (ushort i = 0; i < 6; i++)
                myContract!.MainPage.Source2Select.Button_Selected(i, false);

            myContract!.MainPage.Source2Select.Button_Selected(m.Analog, true);
        }
        private void Zone3SetSourceFb(Message m)
        {

            for (ushort i = 0; i < 6; i++)
                myContract!.MainPage.Source3Select.Button_Selected(i, false);

            myContract!.MainPage.Source3Select.Button_Selected(m.Analog, true);
        }
        private void Zone4SetSourceFb(Message m)
        {

            for (ushort i = 0; i < 6; i++)
                myContract!.MainPage.Source4Select.Button_Selected(i, false);

            myContract!.MainPage.Source4Select.Button_Selected(m.Analog, true);
        }

        private void MediaPlayerObjectPlayerFb(Message m)
        {
            CrestronConsole.PrintLine($"FromMp ={m.Serial}");
            myContract.MediaPlayerPage.MediaPlayer.MediaPlayer_CRPC_FB(m.Serial);
        }

        // -----------------------------------------------------------------------------
        // Why are we changing pages here?
        //
        // This class owns the overall behavior of the touchpanel, including navigation.
        // The hardware doesn't care what page the user is looking at, and the Message
        // Broker is just delivering information. Neither of them should be making UI
        // decisions.
        //
        // When source feedback arrives, we check whether the selected source is one of
        // the NAX media players. If it is, we automatically switch the touchpanel to the
        // media player page so the controls for that source are immediately available.
        //
        // This is exactly the kind of logic that belongs here. We received system state,
        // decided how the UI should react to it, and changed the UI. No need to make the
        // amplifier responsible for page flips. It already has enough to do.
        // -----------------------------------------------------------------------------

        private void checkMediaPlayer(ushort fb)
        {
            var source = NaxSourceConfiguration.GetSourceNumber(1, fb);
            // 0 = Unroute, 1-4 = Digital Inputs, 5-8 = Analog Inputs, 9-16 = Media Players, 17 = AES67 Stream
            // If a Media Player is selected, send the flip to media player message
            if (source > 8 &&  source < 17)
            {
                CrestronConsole.PrintLine("Media Page detected");
                myContract.MediaPlayerPage.VisibilityJoin(true);
                myContract.MediaPlayerPage.VisibilityJoin(false);
                connectCrpc();
            }
                
        }

        // ######################################## Media Player Widget connections.
        private void connectCrpc()
        {
            
            myContract.MediaPlayerPage.MediaPlayer.MediaPlayer_Message_FB(" {\"ver\":\"4.0.0.\",\"tag\":\"01\",\"src\":\"1\"}"); // Send the source message
            myContract.MediaPlayerPage.MediaPlayer.MediaPlayer_Offline(false);
            myContract.MediaPlayerPage.MediaPlayer.MediaPlayer_Player_Name("TEST");
            
        }

        private void MediaPlayer_MediaPlayer_CRPCEvent(object? sender, UIEventArgs e)
        {
            Broker.SendMessage("UiMediaPlayerCrpcMessage", new Message { Serial = e.SigArgs.Sig.StringValue });
        }
    }


}
